// lz-compress: greedy LZ77 over a generated byte buffer (see lz-compress.mi).

use std::time::Instant;

fn generated_input(n: usize) -> Vec<u8> {
    let mut data = Vec::with_capacity(n);
    let mut state: i64 = 11;
    while data.len() < n {
        state = state * 48271 % 2147483647;
        if data.len() > 64 && state % 4 == 0 {
            let back = 1 + ((state / 4) % 60) as usize;
            let length = 3 + (state / 256) % 20;
            let mut k = 0;
            while k < length && data.len() < n {
                data.push(data[data.len() - back]);
                k += 1;
            }
        } else {
            data.push((97 + state % 16) as u8);
        }
    }
    data
}

fn kernel(n: i64) -> String {
    let data = generated_input(n as usize);
    let size = data.len();
    let (mut literals, mut matches, mut hash): (i64, i64, i64) = (0, 0, 0);
    let mut pos = 0;
    while pos < size {
        let (mut best_length, mut best_distance) = (0, 0);
        for start in pos.saturating_sub(255)..pos {
            let mut length = 0;
            while pos + length < size && length < 255 && data[start + length] == data[pos + length] {
                length += 1;
            }
            if length > best_length {
                best_length = length;
                best_distance = pos - start;
            }
        }
        if best_length >= 3 {
            matches += 1;
            hash = (hash * 31 + (best_distance * 256 + best_length) as i64) % 1000000007;
            pos += best_length;
        } else {
            literals += 1;
            hash = (hash * 31 + data[pos] as i64) % 1000000007;
            pos += 1;
        }
    }
    format!("{literals} {matches} {hash}")
}

fn run_hot(n: i64) -> String {
    let expected = kernel(n);
    let mut agree = true;
    for _ in 1..5 {
        let checksum = kernel(n);
        agree = agree && checksum == expected;
    }
    for _ in 0..5 {
        let start = Instant::now();
        let checksum = kernel(n);
        let elapsed = start.elapsed().as_nanos();
        eprintln!("hot_ns={elapsed}");
        agree = agree && checksum == expected;
    }
    if !agree {
        eprintln!("checksum differs between iterations");
        std::process::exit(1);
    }
    expected
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let text = std::fs::read_to_string(&args[1]).unwrap_or_else(|_| std::process::exit(2));
    let input: i64 = text.trim().parse().unwrap_or_else(|_| std::process::exit(2));
    let hot = args.get(2).is_some_and(|a| a == "hot");
    println!("{}", if hot { run_hot(input) } else { kernel(input) });
}
